// M7 task 4: the Thai dish estimates and seed foods. thaiDishes.json is generated by
// scripts/build-foods.mjs from thaiDishes.src.json; this test rebuilds every dish independently
// from the committed USDA subset so the generated values can't drift from their recipes.
import { describe, expect, it } from 'vitest';
import usdaText from './usda-foods.json?raw';
import recipeSrc from './thaiDishes.src.json';
import {
  EDIT_FROM_LABEL,
  PROTEIN_SHAKE_ID,
  SEED_FOODS,
  THAI_DISHES,
  findStaticFood,
} from './foods';
import { checkCopy } from '../../core/trainer/replies';
import type { Food, FoodDbRow } from '../../core/types';

const usda = new Map((JSON.parse(usdaText) as { foods: FoodDbRow[] }).foods.map((r) => [r.id, r]));
const round1 = (x: number): number => Math.round(x * 10) / 10;
const THAI = /[฀-๿]/;

function servingG(f: Food): number {
  if (!('servingLabel' in f.basis)) throw new Error(`${f.id} is per 100 g`);
  return f.basis.servingG ?? NaN;
}

describe('Thai dishes', () => {
  it('has about 40 dishes with unique thai: ids', () => {
    expect(THAI_DISHES.length).toBeGreaterThanOrEqual(38);
    expect(THAI_DISHES.length).toBeLessThanOrEqual(50);
    const ids = THAI_DISHES.map((d) => d.id);
    expect(new Set(ids).size).toBe(ids.length);
    for (const id of ids) expect(id).toMatch(/^thai:[a-z0-9-]+$/);
  });

  it('includes the SPEC examples', () => {
    for (const id of [
      'thai:pad-kra-pao-moo-rice-egg',
      'thai:khao-man-gai',
      'thai:pad-thai-goong',
      'thai:pad-see-ew-moo',
      'thai:khao-pad-moo',
      'thai:tom-yum-goong',
      'thai:kaeng-khiao-wan-gai-rice',
      'thai:som-tum-thai',
      'thai:kuay-teow-ruea',
      'thai:larb-moo',
      'thai:moo-ping-khao-niao',
    ]) {
      expect(findStaticFood(id), id).toBeDefined();
    }
  });

  it.each(THAI_DISHES.map((d) => [d.id, d] as const))(
    '%s is a complete per-plate estimate',
    (_id, d) => {
      expect(d.source).toBe('thai-estimate');
      expect(d.name.trim()).not.toBe('');
      expect(d.nameTh).toMatch(THAI);
      expect(Number.isInteger(d.kcal) && d.kcal > 0).toBe(true);
      expect(d.proteinG).toBeGreaterThanOrEqual(0);
      expect(d.carbsG).toBeTypeOf('number');
      expect(d.fatG).toBeTypeOf('number');
      expect(servingG(d)).toBeGreaterThan(0);
      expect(d.portions).toEqual([
        { label: 'Small', factor: 0.75 },
        { label: 'Regular', factor: 1 },
        { label: 'Large', factor: 1.4 },
      ]);
      expect(d.estimate).toBe(true);
      expect(d.note).toMatch(/^Estimate per /);
      expect(d.note).toMatch(/usda:\d+/);
      expect(checkCopy(d.note ?? '').hits).toEqual([]);
      // kcal agrees with 4/4/9 from the macros (catches a mistyped USDA id or gram amount)
      const atwater = 4 * d.proteinG + 4 * (d.carbsG ?? 0) + 9 * (d.fatG ?? 0);
      expect(Math.abs(atwater - d.kcal) / d.kcal).toBeLessThan(0.15);
    },
  );

  it('matches its reference recipe rebuilt from the committed USDA subset', () => {
    expect(recipeSrc.dishes.map((r) => r.id)).toEqual(THAI_DISHES.map((d) => d.id));
    for (const recipe of recipeSrc.dishes) {
      const sum = { g: 0, kcal: 0, proteinG: 0, carbsG: 0, fatG: 0 };
      for (const ing of recipe.ingredients) {
        const row = usda.get(ing.food);
        expect(row, `${recipe.id}: ${ing.food}`).toBeDefined();
        if (!row) continue;
        sum.g += ing.g;
        sum.kcal += (ing.g * row.kcal) / 100;
        sum.proteinG += (ing.g * row.proteinG) / 100;
        sum.carbsG += (ing.g * (row.carbsG ?? NaN)) / 100;
        sum.fatG += (ing.g * (row.fatG ?? NaN)) / 100;
      }
      const dish = findStaticFood(recipe.id);
      expect(dish, recipe.id).toBeDefined();
      if (!dish) continue;
      expect([dish.kcal, dish.proteinG, dish.carbsG, dish.fatG, servingG(dish)], recipe.id).toEqual(
        [
          Math.round(sum.kcal),
          round1(sum.proteinG),
          round1(sum.carbsG),
          round1(sum.fatG),
          round1(sum.g),
        ],
      );
    }
  });
});

describe('seed foods', () => {
  it('ships the Protein shake with placeholder values to edit from the label', () => {
    const shake = SEED_FOODS.find((f) => f.id === PROTEIN_SHAKE_ID);
    expect(shake).toBeDefined();
    expect(shake?.name).toBe('Protein shake');
    expect(shake?.source).toBe('custom');
    expect(shake?.note).toMatch(/placeholder/i);
    expect(shake?.note).toMatch(/label/i);
    expect(EDIT_FROM_LABEL.has(PROTEIN_SHAKE_ID)).toBe(true);
  });

  it.each(SEED_FOODS.map((f) => [f.id, f] as const))(
    '%s has kcal, protein, a source and a note',
    (_id, f) => {
      expect(f.kcal).toBeGreaterThan(0);
      expect(f.proteinG).toBeGreaterThanOrEqual(0);
      expect(f.source).toBeTypeOf('string');
      expect(f.note?.trim()).toBeTruthy();
      expect(checkCopy(f.note ?? '').hits).toEqual([]);
    },
  );

  it('has ids distinct from the Thai dishes, and findStaticFood finds both', () => {
    const ids = [...SEED_FOODS, ...THAI_DISHES].map((f) => f.id);
    expect(new Set(ids).size).toBe(ids.length);
    expect(findStaticFood(PROTEIN_SHAKE_ID)?.name).toBe('Protein shake');
    expect(findStaticFood('thai:khao-man-gai')?.nameTh).toBe('ข้าวมันไก่');
    expect(findStaticFood('nope')).toBeUndefined();
  });
});
